package android.content;import android.net.Uri;public class Intent {String action,pkg;Uri data;public Intent(String a){action=a;}public Intent(String a,Uri d){action=a;data=d;}public Intent setPackage(String p){pkg=p;return this;}public String getPackage(){return pkg;}public String getAction(){return action;}public Intent setData(Uri u){data=u;return this;}public String getDataString(){return data==null?null:data.toString();}}
